contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the minimal sequence: fund this test contract, transfer funds into C, then call getFirstWithdrawalBonus
    // and observe that address(c).balance decreases by exactly 100 (the bonus) after the call.
    function runTest(address payable recipient, uint fundAmount) public payable {
        // Preconditions: caller supplies Ether to this contract for forwarding
        require(msg.value == fundAmount);
        require(fundAmount >= 100, "need at least 100 to fund bonus");

        // Send the funds into C so it can pay out the bonus
        (bool sentToC, ) = address(c).call{value: fundAmount}("");
        require(sentToC);

        uint before = address(c).balance;

        // Trigger the bonus and withdrawal sequence in C for recipient
        c.getFirstWithdrawalBonus(recipient);

        uint after = address(c).balance;

        // On the original, the contract pays exactly 100 for the bonus; mutant would try to pay 101 and fail or reduce by 101.
        assert(before - after == 100);
    }

    // Allow contract to receive Ether for the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint fund) public payable {
        // we will fund this test contract externally before calling any payable call below
        require(address(this).balance >= fund);
        // send `fund` wei to C so it has balance to pay out
        (bool s, ) = address(c).call{value: fund}("");
        require(s);

        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }

        // General rule: if C had at least the reward amount available, withdrawReward must not revert.
        // We cannot read rewardsForA (private), so we express availability via observation: if the contract's balance
        // before the call was >= address(c).balance afterwards plus any transfer — instead we require that funding
        // provided at least 1 wei so that the mutant (which adds +1) would revert when exact equality fails.
        // To make this general: if we supplied at least 1 wei, the original never reverts on withdraw; the mutant may.

        // Assert that withdrawReward did not revert (original behavior): caller-supplied funding implies sufficient balance
        assert(!reverted);
    }
    receive() external payable {}
}

