    function run(address recipient, uint fundAmount) public payable {
        require(address(this).balance >= fundAmount);
        // fund the contract so it has liquidity to pay rewards
        (bool ok, ) = address(c).call{value: fundAmount}("");
        require(ok);

        // First, call getFirstWithdrawalBonus to set up a reward for recipient.
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) { firstReverted = false; } catch { firstReverted = true; }
        // ensure the setup succeeded on P; if setup reverted, nothing to assert about withdraw
        require(firstReverted == false);

        // Now call withdrawReward(recipient) and observe whether it reverts.
        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }

        // On the original, withdrawReward will not revert because the contract had at least the recorded reward.
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint seedFunds) public payable {
        require(true);
        // Ensure this test contract can fund C so C has enough balance to cover the recorded reward.
        // We cannot access rewardsForA directly, so we fund C with `seedFunds` and rely on the rule to quantify "at least the recorded withdrawable amount" by ensuring we send some funds and then assert based on revert outcome.
        // Transfer Ether to C so it may cover withdrawals. This is a plain transfer to the contract.
        if (seedFunds > 0) {
            require(address(this).balance >= seedFunds);
            (bool sent, ) = address(c).call{value: seedFunds}("");
            require(sent);
        }

        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }

        // General rule: if contract balance is at least seedFunds (i.e., we funded it) then withdrawReward should not revert.
        // Expressed as: if seedFunds > 0 then the call must not have reverted.
        assert(!(seedFunds > 0) || reverted == false);
    }
    receive() external payable { }
}

