pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Receiver attacker;

    function setUp() public { c = new C(); }

    // fuzzed params: recipient address and a flag deciding whether the adversary will revert
    function testFuzz_property(address recipient, bool willRevert) public {
        // keep recipient non-zero to be meaningful
        vm.assume(recipient != address(0));

        // deploy an adversarial receiver that can revert on receive
        attacker = new Receiver(willRevert);

        // We want to route the withdrawReward external call to the adversarial contract.
        // The public API expects an address 'recipient'. If the fuzzer provided an address
        // that is not our attacker, we still pass the attacker's address into the flow
        // by calling getFirstWithdrawalBonus with attacker address so the external call goes to attacker.

        // fund the contract so it can send rewards
        vm.deal(address(c), 1 ether);

        // Call getFirstWithdrawalBonus on the attacker address to set rewardsForA[attacker] += 100 and invoke withdrawReward
        // We call as any EOA; use prank from a non-attacker account to avoid msg.sender coincidences
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp, recipient)))));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        // call with attacker address so withdrawReward will do a low-level call to attacker
        // wrap in try/catch because the call sequence may revert depending on willRevert
        bool ok;
        try c.getFirstWithdrawalBonus(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): After the above, the contract's recorded rewardsForA for the attacker must be zero.
        // We observe this via the autogenerated getter rewardsForA (note: in the original contract it is private, but
        // the problem statement allowed reading via public surface; if rewardsForA is private in code under test, we cannot read it.
        // However the difference can be observed by checking that calling withdrawReward again will not send value (i.e., will try to withdraw 0)
        // We implement an observation by calling withdrawReward(attacker) again and observing whether it attempts to send funds.
        // To detect that, we make the attacker record whether it received value. If rewardsForA was zeroed, second call sends 0 and attacker.receive not invoked.

        // reset attacker received flag
        attacker.resetReceived();

        // Call withdrawReward again and catch revert (should not revert in reference)
        bool ok2;
        try c.withdrawReward(address(attacker)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Now assert that attacker did NOT receive value on the second call (i.e., rewardsForA was zeroed by the first flow in the correct contract)
        // This single assertion is true for the reference for all inputs; the mutant that zeroes after the external call can leave rewardsForA non-zero
        // when the external call reverts, causing the second withdraw to send value and flip attacker.gotPaid()
        assertTrue(!attacker.gotPaid());
    }
}

// adversarial receiver: can be configured to revert on receive; otherwise records if it got ETH
contract Receiver {
    bool public shouldRevert;
    bool public received;

    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
        received = false;
    }

    receive() external payable {
        if (shouldRevert) {
            revert("revert on receive");
        }
        if (msg.value > 0) {
            received = true;
        }
    }

    function gotPaid() external view returns (bool) { return received; }
    function resetReceived() external { received = false; }
}

