pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the recipient address by deploying a helper that can be toggled to revert or accept
    // We fuzz a single boolean flag 'willRevert' to control the helper's behavior (fuzzer provides it)
    // and an address seed so the fuzzer explores different caller identities when funding/pranking.
    function testFuzz_property(bool willRevert, uint160 addrSeed) public {
        // Keep address variability wide: construct a pseudo-random address from seed
        address recipient = address(uint160(addrSeed));

        // Deploy a helper contract that either accepts or reverts on receive based on willRevert
        ReverterOrReceiver helper = new ReverterOrReceiver(willRevert);

        // Ensure helper has some ETH so that withdrawReward can send value
        vm.deal(address(helper), 100 ether);

        // First call: call getFirstWithdrawalBonus(helper) as any caller.
        // Use vm.prank with an arbitrary fuzzed caller derived from addrSeed to vary msg.sender
        address caller = address(uint160(addrSeed ^ 0xdeadbeef));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool firstSucceeded = true;
        try c.getFirstWithdrawalBonus(address(helper)) {
            firstSucceeded = true;
        } catch {
            firstSucceeded = false;
        }

        // Second call: attempt again as same caller. On the correct contract, if firstSucceeded==true,
        // the second call MUST revert (claimedBonus set). On the mutant it may succeed for some inputs.
        vm.prank(caller);
        bool secondSucceeded = true;
        try c.getFirstWithdrawalBonus(address(helper)) {
            secondSucceeded = true;
        } catch {
            secondSucceeded = false;
        }

        // General rule (single assertion): For all inputs where the first call succeeded, the second call MUST revert.
        // This is observed via the contract's public behavior: the success flag of the second invocation must be false
        // whenever the first invocation succeeded. The correct contract satisfies this for every input; the mutant
        // that omits setting claimedBonus will violate it for some inputs (the fuzzer should find one).
        if (firstSucceeded) {
            assertTrue(!secondSucceeded);
        } else {
            // If the first call failed, we make no requirement about the second call (it may fail too).
            assertTrue(true);
        }
    }
}

// Helper that either reverts on receive or accepts; this models an adversarial/external recipient
contract ReverterOrReceiver {
    bool public willRevert;
    constructor(bool _willRevert) payable {
        willRevert = _willRevert;
    }
    receive() external payable {
        if (willRevert) revert("nope");
    }
}

